import { test } from '../../fixtures/test';
import { attachConsoleGuard, type ConsoleGuard } from '../../helpers/console-guard';
import { captureEvidence, recordFailureEvidence } from '../../helpers/evidence';
import { step } from '../../helpers/steps';
import { TaskListPage } from '../../pages/TaskListPage';

let guard: ConsoleGuard;
test.beforeEach(async ({ page }) => {
  guard = attachConsoleGuard(page);
});
test.afterEach(async ({ page }, testInfo) => {
  await recordFailureEvidence(page, testInfo);
  await guard.report(testInfo);
});

test.describe('FR-010, FR-011, US3-AS1 … US3-AS3: delete a task — run group serial:task-list', () => {
  // serial:task-list — the cases delete tasks of the GLOBAL list, so they must not run beside each other
  // (--workers 1); each case owns its tasks through its run prefix; mode 'default' keeps them independent
  test.describe.configure({ mode: 'default' });

  test('[TC-TODO-018] Deleting "Buy milk" removes it at once with no confirmation, and the other task remains', { tag: ['@positive', '@smoke', '@run:serial-task-list'] }, async ({ page, context, qaRun }, testInfo) => {
    const buyMilk = `${qaRun}-Buy milk`;
    const callSam = `${qaRun}-Call Sam`;
    await step('Setup [D2]: add "QA-<run>-Buy milk" and then "QA-<run>-Call Sam" through "New task"', () => TaskListPage.addThroughPage(context, [buyMilk, callSam]));
    const taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — both tasks are listed', async () => {
      await taskList.waitForListReady();
      await taskList.expectCaseOrder(qaRun, [callSam, buyMilk]);
    });
    await step('Click "Delete" of "QA-<run>-Buy milk" — it disappears without any confirmation dialog', async () => {
      await taskList.task(buyMilk).delete();
      await taskList.expectNoTaskTitled(buyMilk);
      await taskList.expectNoDialogShown();
    });
    await captureEvidence(taskList.page, testInfo);
    await step('Check the task list — of the case\'s tasks only "QA-<run>-Call Sam" remains', () => taskList.expectCaseOrder(qaRun, [callSam]));
  });

  test('[TC-TODO-019] A completed task can be deleted', { tag: ['@positive', '@run:serial-task-list'] }, async ({ page, context, qaRun }, testInfo) => {
    const buyMilk = `${qaRun}-Buy milk`;
    await step('Setup [D2]: add "QA-<run>-Buy milk" through "New task"', () => TaskListPage.addThroughPage(context, [buyMilk]));
    const taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — "QA-<run>-Buy milk" is listed with "Mark as completed"', async () => {
      await taskList.waitForListReady();
      await taskList.task(buyMilk).expectNotCompleted();
    });
    await step('Click "Mark as completed" of "QA-<run>-Buy milk" — the task shows the text "Completed"', async () => {
      await taskList.task(buyMilk).markCompleted();
      await taskList.task(buyMilk).expectCompleted();
    });
    await step('Click "Delete" of "QA-<run>-Buy milk" — it disappears from the list', async () => {
      await taskList.task(buyMilk).delete();
      await taskList.expectNoTaskTitled(buyMilk);
    });
    await captureEvidence(taskList.page, testInfo);
    await step('Check the task list — no task titled "QA-<run>-Buy milk" is listed', () => taskList.expectNoTaskTitled(buyMilk));
  });

  test('[TC-TODO-020] A deleted task is not shown after reopening, and no restore action exists', { tag: ['@positive', '@run:serial-task-list'] }, async ({ page, context, qaRun }, testInfo) => {
    const buyMilk = `${qaRun}-Buy milk`;
    await step('Setup [D2]: add "QA-<run>-Buy milk" through "New task"', () => TaskListPage.addThroughPage(context, [buyMilk]));
    let taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — "QA-<run>-Buy milk" is listed', async () => {
      await taskList.waitForListReady();
      await taskList.expectTaskListed(buyMilk);
    });
    await step('Click "Delete" of "QA-<run>-Buy milk" — it disappears from the list', async () => {
      await taskList.task(buyMilk).delete();
      await taskList.expectNoTaskTitled(buyMilk);
    });
    taskList = await step('Close the browser window and open [E1] in a new browser window — "Loading tasks…" appears', () => taskList.reopenInNewWindow());
    await step('Wait until "Loading tasks…" clears — no task titled "QA-<run>-Buy milk" is listed', async () => {
      await taskList.waitForListReady();
      await taskList.expectNoTaskTitled(buyMilk);
    });
    await captureEvidence(taskList.page, testInfo);
    await step('Check the page for a way to restore — no "Undo", "Restore" or "Deleted tasks" action', () => taskList.expectNoRestoreAction());
  });
});

test.describe('FR-006, US3-AS4: deleting the only task — run group serial:empty-list', () => {
  // serial:empty-list — [D1] empties the GLOBAL list, so this case runs alone (--workers 1)
  test.describe.configure({ mode: 'default' });

  test('[TC-TODO-021] Deleting the only task shows "No tasks yet."', { tag: ['@positive', '@run:serial-empty-list'] }, async ({ page, qaRun, emptyTaskList }, testInfo) => {
    void emptyTaskList;
    const onlyTask = `${qaRun}-Only task`;
    const taskList = await step('Open the To-Do List application [E1] — the text "Loading tasks…" appears', () => TaskListPage.open(page));
    await step('Wait until "Loading tasks…" clears — "No tasks yet." is shown and no task is listed', async () => {
      await taskList.waitForListReady();
      await taskList.expectEmptyList();
    });
    await step('Type "QA-<run>-Only task" [D2] in "New task" — the field shows it', () => taskList.typeTitle(onlyTask));
    await step('Click "Add" — "QA-<run>-Only task" is the only task and "No tasks yet." is gone', async () => {
      await taskList.clickAdd();
      await taskList.expectFirstTask(onlyTask);
      await taskList.expectTaskCount(1);
    });
    await step('Click "Delete" of "QA-<run>-Only task" — it disappears from the list', async () => {
      await taskList.task(onlyTask).delete();
      await taskList.expectNoTaskTitled(onlyTask);
    });
    await captureEvidence(taskList.page, testInfo);
    await step('Check the task list — "No tasks yet." is shown and no task is listed', () => taskList.expectEmptyList());
  });
});
